float PI = acos(-1.);
mat2 rot(float r){
    vec2 s = vec2(cos(r),sin(r));
    return mat2(s.x,s.y,-s.y,s.x);
}
float cube(vec3 p,vec3 s){

    vec3 q = abs(p);
    vec3 m = max(s-q,0.);
    return length(max(q-s,0.))-min(min(m.x,m.y),m.z);
}
#define Q(p) p *= r(round(atan(p.x, p.y) * 4.) / 4.)
#define r(a) mat2(cos(a + asin(vec4(0,1,-1,0))))

vec4 map( in vec3 p )
{

vec3 r2 = normalize(vec3(p.xy, 1.0 - dot(p.xy, p.xy) *1.5));

   float d = cube(p,vec3(1.0));
vec3 col = vec3(0);
   float s = 1.0;
   float ite = 4.0;

   for( int m=0; m<5; m++ )
   {
      vec3 a = mod( p*s*r2, 2.0 )-1.0;

      s *= 3.0;
      vec3 r = abs(1.1 - 3.0*abs(a));

      float da = max(r.x,r.y);
      float db = max(r.y,r.z);
      float dc = max(r.z,r.x);
      float k = 2.0*pow(abs(sin(0.0*iTime)),0.2);
       if(r.x<r.y)col.z+=1.2*abs((float(m)-k))/ite;
        if(r.y>r.z)col.y+=1.*abs((float(m)-k))/ite,col.z += 0.2*abs((float(m)-k))/ite;
        if(r.x>r.z)col.x+=1.2*abs((float(m)-k))/ite;
      float c = (min(da,min(db,dc))-1.0)/s;

      d = max(d,c);
   }

   return vec4(col,d);
}
